	'smp_intro' => 'Installa una piccola applicazione di esempio: 5 utenti con 5 livelli di accesso, moduli per clienti, prodotti e ordini, e un modulo con ogni tipo di oggetto e formato. Ogni record, tabella e ID inizia con sample_, quindi può essere rimosso completamente. I moduli sono scritti nel formato di nuBuilder Forte e si aprono anche in nuBuilder Forte. Include anche quattro dashboard: nella pagina iniziale degli utenti di esempio, nel modulo clienti (scheda Statistics) e nel modulo di avvio di esempio.',
