	'rd_help' => 'Guida',
	'rd_help_text' => 'Trascina i campi da sinistra su una sezione, oppure clicca Campo / Testo / Rettangolo / Linea / Immagine. Le sezioni si stampano in quest\'ordine: intestazione del report (una volta), intestazione di pagina (ogni pagina), intestazioni di gruppo, dettaglio (ogni riga), piè di gruppo, piè di pagina, piè del report.\\nSposta gli oggetti con il mouse (anche in un\'altra sezione) o con i tasti freccia (Maiusc = 4 mm, Alt = 0,25 mm); le maniglie cambiano la dimensione. Maiusc-clic o un riquadro per selezionarne più d\'uno, poi i pulsanti di allineamento.\\nCtrl+Z / Ctrl+Y annulla e ripeti, Ctrl+C / Ctrl+V copia, Ctrl+D duplica, Canc elimina, Ctrl+S salva.\\nCampi: una colonna, SUM(colonna) o AVERAGE(a, b) – somme per gruppo di ordinamento. I testi possono contenere #page#, #pages#, #code#, #description#, #nu_date# e ogni variabile hash (p. es. campi del form di avvio).\\nUn valore che inizia con #B#rrggbb| o #F#rrggbb| riceve quel colore di sfondo / testo (formattazione condizionale dalla sorgente dati).\\nL\'anteprima stampa il layout attuale con criteri vuoti; il layout è salvato nel formato di nuBuilder Forte.',
