	'secchk_set_rights_globeadmin_only' => 'Solo il globeadmin concede diritti di amministrazione',
	'secchk_set_rights_globeadmin_only_tip' => 'I diritti salva, aggiungi, nuovo, elimina e clona su moduli, procedure, generatore SQL, configurazione, utenti e livelli di accesso danno il controllo totale (codice sul server, diritti propri). Attivo: solo il globeadmin li concede o assegna livelli di accesso che li contengono; nessun altro modifica tali utenti; nessuno modifica il proprio livello di accesso o i suoi diritti; gli altri non possono salvare questi moduli di sistema tramite i moduli.',
	'secchk_set_protect_fields' => 'Non salvare dal browser i campi di sola lettura e nascosti',
	'secchk_set_protect_fields_tip' => 'I campi con accesso «sola lettura» o «nascosto» mantengono il valore salvato, qualunque cosa invii il browser. Disattivo = come nuBuilder Forte: il JavaScript che compila questi campi (ad es. nuSetValue su un campo nascosto) continua a funzionare.',
	'secchk_set_record_check' => 'Record solo tramite l’elenco del modulo',
	'secchk_set_record_check_tip' => 'Un record può essere aperto, salvato o eliminato solo se l’SQL dell’elenco del modulo (con le variabili hash dell’utente) lo trova. I moduli senza SQL dell’elenco e l’SQL che richiede codice Before Browse non vengono controllati. Disattivo = come nuBuilder Forte.',
	'secchk_set_field_access_ga' => 'Applica le regole di accesso ai dati al globeadmin',
